; sfx.asm - generated by WebSidTracker. Edit the sound effects in the tracker, not here.
; websidtracker format 2, release 0.1.0
; Play one with:  lda #SFX_NAME : ldx #voice : jsr sfx_play       (voice 0, 1 or 2; see docs/player.md)
; sfx_voice holds the voice each effect was made for in the tracker; the game may use another one.

SFX_ZAP                 = 0    ; zap
SFX_TING                = 1    ; ting

sfx_lo
        !byte <sfx_0, <sfx_1

sfx_hi
        !byte >sfx_0, >sfx_1

sfx_voice
        !byte 2, 0

sfx_count
        !byte 2

sfx_0    ; zap
        !byte 1                         ; speed: frames per tick
        !byte $61, 2                    ; instrument 2
        !byte $48, 6                    ; C-6, 6 ticks
        !byte $62                       ; legato: next note keeps the envelope
        !byte $3C, 4                    ; C-5, 4 ticks
        !byte $60, 1                    ; rest, 1 ticks
        !byte $FF                       ; end of the effect

sfx_1    ; ting
        !byte 3                         ; speed: frames per tick
        !byte $61, 1                    ; instrument 1
        !byte $4E, 2                    ; F#6, 2 ticks
        !byte $FF                       ; end of the effect
